function autohuurAlgemeen() {
  const d = AUTOHUUR_DATA; const oph = { balie: 'balie', shuttle: 'shuttle', vliegveld: 'vliegveld', aflevering: 'aflevering', kantoor: 'kantoor' };
  return {
    id: 'autohuur', peildatum: d.peildatum,
    onderwerp: L5('autoverhuurder', 'car rental company', 'Autovermietung', 'empresa de alquiler de autos', 'locadora de carros'),
    h1: L5('Auto huren op Curaçao: welke verhuurder past bij jou?', 'Curaçao car rental: which company fits your trip?', 'Mietwagen auf Curaçao: welcher Vermieter passt zu dir?', 'Alquiler de autos en Curazao: ¿qué empresa te conviene?', 'Aluguel de carro em Curaçao: qual locadora combina com você?'),
    titel: L5('Auto huren op Curaçao: alle {n} verhuurders vergeleken', 'Curaçao Car Rental: All {n} Companies Compared', 'Mietwagen Curaçao: alle {n} Vermieter im Vergleich', 'Alquiler de autos en Curazao: {n} empresas comparadas', 'Aluguel de carro em Curaçao: {n} locadoras comparadas'),
    metaDesc: L5('', '', '', 'Comparamos {n} empresas de alquiler de autos en Curazao: reseñas, ventajas y desventajas, depósito y recogida en el aeropuerto. Elige en 4 preguntas.', 'Comparamos {n} locadoras de carros em Curaçao: avaliações, prós e contras, caução e retirada no aeroporto. Escolha em 4 perguntas.'),
    kort: L5('', '', '', 'Comparamos {n} empresas en Curazao por reseñas, depósito, seguro y forma de recogida. Las empresas locales puntúan entre 4,6 y 5,0 en Google; las marcas del aeropuerto entre 2,2 y 4,3.', 'Comparamos {n} locadoras em Curaçao por avaliações, caução, seguro e retirada. As locadoras locais têm notas de 4,6 a 5,0 no Google; as marcas do aeroporto, de 2,2 a 4,3.'),
    vragen: [
      { q: L5('Waar wil je de auto ophalen?', 'Where do you want to pick up the car?', 'Wo möchtest du das Auto abholen?', '¿Dónde quieres recoger el auto?', 'Onde você quer retirar o carro?'), opties: [
        { label: L5('Op het vliegveld', 'At the airport', 'Am Flughafen', 'En el aeropuerto', 'No aeroporto'), plus: ['balie', 'vliegveld', 'shuttle'] },
        { label: L5('Bezorgd bij mijn hotel', 'Delivered to my hotel', 'Zustellung ans Hotel', 'Entregado en mi hotel', 'Entregue no meu hotel'), plus: ['aflevering'], vereist: 'aflevering' },
        { label: L5('Maakt niet uit', 'No preference', 'Egal', 'No importa', 'Tanto faz'), plus: [] }] },
      { q: L5('Wat voor auto?', 'What kind of car?', 'Was für ein Auto?', '¿Qué tipo de auto?', 'Que tipo de carro?'), opties: [
        { label: L5('Kleine auto', 'Small car', 'Kleinwagen', 'Auto pequeño', 'Carro pequeno'), plus: [] },
        { label: L5('Jeep of 4x4', 'Jeep or 4x4', 'Jeep oder 4x4', 'Jeep o 4x4', 'Jipe ou 4x4'), plus: ['jeep'], vereist: 'jeep' },
        { label: L5('7 personen', '7 seats', '7 Sitze', '7 plazas', '7 lugares'), plus: ['zeven'], vereist: 'zeven' }] },
      { q: L5('Wat is het belangrijkst?', 'What matters most?', 'Was ist am wichtigsten?', '¿Qué es lo más importante?', 'O que é mais importante?'), opties: [
        { label: L5('Beste reviews', 'Best reviews', 'Beste Bewertungen', 'Mejores reseñas', 'Melhores avaliações'), plus: [] },
        { label: L5('Geen of lage borg', 'No or low deposit', 'Keine oder niedrige Kaution', 'Sin depósito o depósito bajo', 'Sem caução ou caução baixa'), plus: ['borglaag'] }] }],
    items: d.verhuurders.map(v => ({ id: v.id, naam: v.naam, url: v.url, soort: v.type === 'internationaal' ? L5('internationaal', 'international', 'international', 'internacional', 'internacional') : L5('lokaal', 'local', 'lokal', 'local', 'local'),
      plaats: null, tags: [...(v.ophalen || []).map(o => oph[o]).filter(Boolean), ...(v.jeep ? ['jeep'] : []), ...(v.zevenPersoons ? ['zeven'] : []), ...(v.borgLaag ? ['borglaag'] : [])],
      prijs: v.prijs ? { bedrag: v.prijs.bedrag, valuta: v.prijs.valuta, eenheid: L5('per dag', 'per day', 'pro Tag', 'por día', 'por dia') } : null, feiten: [], scores: v.scores, voor: v.voor, tegen: v.tegen, bronnen: v.bronnen })),
    tussenpartijen: (d.brokers || []).map(b => ({ naam: b.naam, url: null, uitleg: b.tegen })), tips: d.tips, faq: d.faq
  };
}

