function kop(m, M, titel, desc, canon, alts, schema) {
  return '<!doctype html><html lang="' + M.lang + '"><head><meta charset="utf-8"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2064%2064%27%3E%3Crect%20width%3D%2764%27%20height%3D%2764%27%20rx%3D%2714%27%20fill%3D%27%232B47C4%27%2F%3E%3Cpath%20d%3D%27M18%2033l9%209%2019-20%27%20fill%3D%27none%27%20stroke%3D%27%23fff%27%20stroke-width%3D%277%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titel) + '</title><meta name="description" content="' + esc(desc) + '"><meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large"><link rel="canonical" href="' + canon + '">'
    + alts.map(([l, u]) => '<link rel="alternate" hreflang="' + l + '" href="' + u + '">').join('') + '<link rel="alternate" hreflang="x-default" href="' + (alts.find(a => a[0] === 'en') || alts[0])[1] + '">'
    + '<meta property="og:title" content="' + esc(titel) + '"><meta property="og:description" content="' + esc(desc) + '"><meta property="og:url" content="' + canon + '"><meta property="og:type" content="article"><meta property="og:locale" content="' + M.locale.replace('-', '_') + '">'
    + '<script type="application/ld+json">' + JSON.stringify(schema).replace(/</g, '\\u003c') + '</script><style>' + CSS + '</style></head><body>';
}
const balk = (m, kruim, talen) => '<header class="top"><div class="top-in"><a class="brand" href="/">' + CUR_MARKT[m].merk + '</a>' + (kruim ? '<a class="kruim" href="' + kruim[0] + '">' + esc(kruim[1]) + '</a>' : '') + '<nav class="langs" aria-label="Language">' + talen + '</nav></div></header>';
const talenNav = (m, urlVan) => Object.keys(CUR_MARKT).map(k => '<a href="' + urlVan(k) + '" hreflang="' + k + '"' + (k === m ? ' aria-current="true"' : '') + '>' + k.toUpperCase() + '</a>').join('');
const voet = (m, d) => '</main><footer><div class="in">' + esc(T[m].mis) + ' <a href="https://wa.me/31655395630" rel="nofollow">' + esc(T[m].wa) + '</a> · ' + esc(d) + '<br>' + esc(CUR_MARKT[m].naam) + ' · AdsFair B.V., Gouda · KvK 60126035 · <a href="' + hubUrl(m) + '">' + esc(T[m].home) + '</a> · <a href="/privacy">' + PRIV[m] + '</a></div></footer><script defer src="/api/keuze-updates?op=deel" data-deel="1"></script>';
