export const meetJs = (m, pagina) => '(function(){function bron(){var r=document.referrer||"",u=location.search;if(/utm_source=(chatgpt|openai|perplexity|copilot|gemini|claude)/i.test(u))return "ai";try{var h=r?new URL(r).hostname:"";if(!h||h===location.hostname)return h?"intern":"direct";if(/chatgpt|openai|perplexity|copilot|gemini\\.google|claude\\.ai|you\\.com|phind/.test(h))return "ai";if(/google\\.|bing\\.|duckduckgo|yahoo\\.|ecosia|qwant|startpage|yandex|brave/.test(h))return "zoek";return "overig"}catch(e){return "overig"}}function hit(k){try{var d=new Date().toISOString().slice(0,10).replace(/-/g,"");navigator.sendBeacon("/api/keuze-tools?tool=cur&op=hit",new Blob([JSON.stringify({m:"' + m + '",p:"' + pagina + '",k:k})],{type:"text/plain"}))}catch(e){}}window.__curHit=hit;hit("view-"+bron());var gezien={};function tops(){var t=document.getElementById("ah-top");if(!t)return;t.querySelectorAll("[data-id]").forEach(function(k){var id=k.getAttribute("data-id");if(id&&!gezien[id]){gezien[id]=1;hit("top-"+id.slice(0,44))}})}tops();document.addEventListener("change",function(){setTimeout(tops,60)});document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest("a[data-out]");if(a)hit("out-"+a.getAttribute("data-out"))})})();';

